// Validate schema and ranges; convert ts to UTC ISO string
const p = msg.payload;
const errs = [];
function t(v){ return typeof v; }

if (t(p.temp) !== 'number') errs.push('temp number required');
if (t(p.g_force) !== 'number') errs.push('g_force number required');
if (t(p.parcel_id) !== 'string' || !p.parcel_id.trim()) errs.push('parcel_id string required');
if (!p.ts) errs.push('ts required');

// basic sanity ranges (but allow extremes to be stored while flagged)
if (p.temp < -50 || p.temp > 85) errs.push('temp out of sensor range');
if (p.g_force < 0 || p.g_force > 16) errs.push('g_force out of sensor range');

let ts;
try { ts = new Date(p.ts); if (isNaN(ts.getTime())) throw new Error('bad'); }
catch(e){ errs.push('ts invalid datetime'); }

if (errs.length){
    node.warn('Validation failed: '+errs.join('; '));
    // still store as raw with a flag? For simplicity, drop invalids:
    msg.validation_error = errs;
    return null;
}

// Normalize
msg.payload = {
  parcel_id: p.parcel_id,
  temp_c: p.temp,
  g_force: p.g_force,
  ts_utc: new Date(ts.toISOString()).toISOString(), // ensure UTC
  raw_json: JSON.stringify(p)
};
msg.received_at = new Date().toISOString();
return msg;
